export const getMetabaseQueryIdByQueryName = (queryName: string): number => {
  if (!metabaseQueryIds[envConfig.NODE_ENV]) {
    throw new Error(`Environment not found: ${envConfig.NODE_ENV}`);
  }
  const key = metabaseQueryIds[envConfig.NODE_ENV][queryName];
  if (!key) {
    throw new Error(
      `Metabase query ID not found for query name: ${queryName} in environment: ${envConfig.NODE_ENV}`
    );
  }
  return key;
};
